return await (async function decodeTelegram(input,config,context,group){
  const fail=()=>{throw Error('Invalid Telegram update');};
  const record=x=>x!==null&&typeof x==='object'&&!Array.isArray(x);
  const integer=x=>Number.isSafeInteger(x);
  const text=(x,max=4096)=>{if(x==null)return null;if(typeof x!=='string'||x.length>max||(/[\uD800-\uDBFF](?![\uDC00-\uDFFF])|(?<![\uD800-\uDBFF])[\uDC00-\uDFFF]/u).test(x))fail();return x;};
  if(!record(input)||!integer(input.update_id)||input.update_id<0)fail();
  if(new TextEncoder().encode(JSON.stringify(input)).length>65536)fail();
  const kinds=group==='message'?['message','edited_message','channel_post','edited_channel_post']:['callback_query'];
  const present=kinds.filter(k=>Object.hasOwn(input,k));
  if(!present.length)return {__skip:true};
  if(present.length!==1)fail();
  const kind=present[0],item=input[kind];if(!record(item))fail();
  let resource;
  if(group==='message'){
    if(!integer(item.message_id)||!integer(item.date)||item.date<0||!record(item.chat)||!integer(item.chat.id)||!['private','group','supergroup','channel'].includes(item.chat.type))fail();
    if(item.from!==undefined&&(!record(item.from)||!integer(item.from.id)))fail();
    resource={messageId:item.message_id,chatId:String(item.chat.id),chatType:item.chat.type,senderId:item.from?String(item.from.id):null,text:text(item.text),caption:text(item.caption,1024),sentAt:item.date};
  }else{
    if(typeof item.id!=='string'||!item.id||item.id.length>256||!record(item.from)||!integer(item.from.id))fail();
    if(item.message!==undefined&&(!record(item.message)||!record(item.message.chat)||!integer(item.message.chat.id)||!integer(item.message.message_id)))fail();
    resource={callbackId:item.id,senderId:String(item.from.id),chatId:item.message?String(item.message.chat.id):null,messageId:item.message?.message_id??null,inlineMessageId:text(item.inline_message_id,256),data:text(item.data,64),gameShortName:text(item.game_short_name,256)};
  }
  if(!record(config)||Object.keys(config).some(k=>!['chatId','senderId','$timeoutMs','$retries','$retryDelayMs','$workerPool','$workerRequirements','$connection'].includes(k)))throw Error('Invalid Telegram filters');
  for(const key of ['chatId','senderId'])if(config[key]!==undefined&&(typeof config[key]!=='string'||config[key].length>64))throw Error('Invalid Telegram filters');
  if(config.chatId&&resource.chatId!==config.chatId||config.senderId&&resource.senderId!==config.senderId)return {__skip:true};
  const key='ingress.telegram.'+group+'.seen',seen=await context.state.get(key,[]);
  if(!Array.isArray(seen)||seen.length>100||seen.some(n=>!integer(n)))throw Error('Invalid Telegram checkpoint');
  if(seen.includes(input.update_id))return {__skip:true};
  await context.state.set(key,[...seen,input.update_id].slice(-100));
  return {event:{updateId:input.update_id,kind,resource}};
})(context.input,config,context,"message");

